        o.blend_op = s.blend_op == 1 ? 2 : s.blend_op == 2 ? 3 : 1;
        if (s.blend_mode == 3) { o.src = 2; o.dst = 2; additive = true; }
        else if (s.blend_mode == 4) { o.src = 2; o.dst = 4; additive = true; }
        else { o.src = 5; o.dst = 6; }
